"""Exercise actual private recovery transitions with deterministic preferences doubles."""
from pathlib import Path
import subprocess,tempfile
root=Path(__file__).resolve().parents[1]
sources={
'android/content/Context.java': '''package android.content;import java.util.*;public class Context{public static final int MODE_PRIVATE=0;public final Prefs prefs=new Prefs();public Prefs getSharedPreferences(String n,int m){return prefs;}public static class Prefs{Map<String,Object> data=new HashMap<>();public boolean fail;public String getString(String k,String d){return (String)data.getOrDefault(k,d);}public boolean getBoolean(String k,boolean d){return (Boolean)data.getOrDefault(k,d);}public int getInt(String k,int d){return (Integer)data.getOrDefault(k,d);}public Editor edit(){return new Editor(this);} }public static class Editor{Prefs p;Map<String,Object> puts=new HashMap<>();Set<String> removes=new HashSet<>();Editor(Prefs p){this.p=p;}public Editor putString(String k,String v){puts.put(k,v);return this;}public Editor putBoolean(String k,boolean v){puts.put(k,v);return this;}public Editor putInt(String k,int v){puts.put(k,v);return this;}public Editor remove(String k){removes.add(k);return this;}public boolean commit(){if(p.fail)return false;for(String k:removes)p.data.remove(k);p.data.putAll(puts);return true;}}}''',
'com/elitedarkkaiser/nubialy/ModuleStatus.java': '''package com.elitedarkkaiser.nubialy;public class ModuleStatus{static boolean active=true;public static boolean isActive(){return active;}}''',
'com/elitedarkkaiser/nubialy/GuardReader.java': '''package com.elitedarkkaiser.nubialy;public class GuardReader{static String boot="12345678-1234-1234-1234-123456789abc",id=boot;public static String bootId(){return boot;}public static String inspectEnabled(){return id;}public static PreviewPolicy.Permit inspectPreview(){return null;}public static PreviewPolicy.Permit inspectClock(){return null;}}''',
'com/elitedarkkaiser/nubialy/RecoveryStoreTest.java': '''package com.elitedarkkaiser.nubialy;import android.content.Context;public class RecoveryStoreTest{static void check(boolean b){if(!b)throw new AssertionError();}public static void main(String[]a){Context c=new Context();check(!RecoveryStore.enabledAllowed(c,GuardReader.id));check(RecoveryStore.allowEnabled(c));check(RecoveryStore.enabledAllowed(c,GuardReader.id));check(RecoveryStore.claimStartup(c,10));for(int i=0;i<10;i++)check(RecoveryStore.claimStartup(c,10));check(c.prefs.getInt("startup_attempts",0)==1);check(RecoveryStore.claimStartup(c,11));check(RecoveryStore.claimStartup(c,12));check(!RecoveryStore.claimStartup(c,13));check(!RecoveryStore.enabledAllowed(c,GuardReader.id));check(c.prefs.getBoolean("restart_recovery_stopped",false));check(RecoveryStore.allowEnabled(c));check(RecoveryStore.claimStartup(c,14));check(RecoveryStore.claimSensorStartup(c,30));check(RecoveryStore.claimSensorStartup(c,30));check(c.prefs.getInt("startup_attempts",0)==1&&c.prefs.getInt("sensor_startup_attempts",0)==1);check(RecoveryStore.claimSensorStartup(c,31));check(RecoveryStore.claimSensorStartup(c,32));check(!RecoveryStore.claimSensorStartup(c,33));check(!RecoveryStore.enabledAllowed(c,GuardReader.id));check(RecoveryStore.allowEnabled(c));check(RecoveryStore.claimSensorStartup(c,34));check(c.prefs.getInt("sensor_startup_attempts",0)==1);check(RecoveryStore.claimLauncherStartup(c,50));check(RecoveryStore.claimLauncherStartup(c,50));check(c.prefs.getInt("launcher_startup_attempts",0)==1);check(RecoveryStore.claimLauncherStartup(c,51));check(RecoveryStore.claimLauncherStartup(c,52));check(!RecoveryStore.claimLauncherStartup(c,53));check(!RecoveryStore.enabledAllowed(c,GuardReader.id));check(RecoveryStore.allowEnabled(c));check(LauncherPreferences.activate(c,new LauncherStyle(80,true)));check(LauncherPreferences.active(c).custom());GuardReader.boot="00000000-1234-1234-1234-123456789abc";check(RecoveryStore.claimStartup(c,20));check(c.prefs.getInt("startup_attempts",0)==1);check(RecoveryStore.stop(c));check(!LauncherPreferences.active(c).custom());check(!RecoveryStore.enabledAllowed(c,GuardReader.id));c.prefs.fail=true;check(!RecoveryStore.allowEnabled(c));check(!RecoveryStore.enabledAllowed(c,GuardReader.id));System.out.println("Production recovery store checks passed: explicit arm, same-process resume, restart cutoff, new boot, durable disarm and failed persistence");}}'''}
with tempfile.TemporaryDirectory(prefix='nubialy-recovery-') as work:
    work=Path(work)
    for name,s in sources.items():p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
    files=[str(p) for p in work.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy'/n) for n in ['RecoveryStore.java','PreviewPolicy.java','ClockEnabledPolicy.java','LauncherStyle.java','LauncherPreferences.java']]
    subprocess.run(['java','com.sun.tools.javac.Main','-d',str(work/'classes'),*files],check=True)
    subprocess.run(['java','-cp',str(work/'classes'),'com.elitedarkkaiser.nubialy.RecoveryStoreTest'],check=True)
